"""Build llms-full.txt from the canonical references linked by llms.txt."""

from __future__ import annotations

import argparse
from pathlib import Path
import re

from tools.config import ROOT


def render_reference(root: Path = ROOT) -> str:
    index = (root / "llms.txt").read_text(encoding="utf-8")
    paths = dict.fromkeys(
        target.partition("#")[0]
        for target in re.findall(r"\[[^\]]+\]\(([^)]+)\)", index)
        if target.startswith(("docs/", "compiler/sdk/")))
    sections = [
        "# Vela language and SDK reference",
        "Generated by python -m tools.llms from llms.txt and the canonical source files.",
        "Edit the linked source documents, then regenerate this file.",
    ]
    for relative in paths:
        source = (root / relative).read_text(encoding="utf-8").rstrip()
        sections.append(f"# Source file {relative}")
        sections.append(source if relative.endswith(".md") else "~~~vela\n" + source + "\n~~~")
    return "\n\n".join(sections) + "\n"


def main() -> None:
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument("--check", action="store_true")
    arguments = parser.parse_args()
    output = ROOT / "llms-full.txt"
    reference = render_reference()
    if arguments.check:
        if output.read_text(encoding="utf-8") != reference:
            parser.exit(1, "llms-full.txt is stale; run python -m tools.llms\n")
    else:
        output.write_text(reference, encoding="utf-8", newline="\n")


if __name__ == "__main__":
    main()
